  'purpose.developerEntry': ['開發者：找專案與夥伴', 'Developer: find projects and teammates', '開発者：案件と仲間を探す', '개발자: 프로젝트와 팀원 찾기', 'Desarrollador: buscar proyectos y compañeros'],
  'purpose.entryGroup': ['商品、創作與開發合作入口', 'Product, creative and development opportunities', '商品・創作・開発の参加入口', '상품, 창작, 개발 참여', 'Oportunidades de productos, creación y desarrollo'],
